import json
import pandas as pd

def to_status(value):
    if value is None:
        return None
    if isinstance(value, bool):
        return 'active' if value else 'inactive'
    s = str(value).strip().lower()
    if s in ('true', '1', 'yes', 'active'):
        return 'active'
    if s in ('false', '0', 'no', 'inactive'):
        return 'inactive'
    return str(value)

sources = {}

a = json.load(open('/data/source_a/users.json'))
sources['source_a'] = pd.DataFrame(a).rename(columns={'id': 'user_id', 'full_name': 'name', 'registration_date': 'created_date'})

b = pd.read_csv('/data/source_b/users.csv').rename(columns={'email_address': 'email', 'created_at': 'created_date', 'is_active': 'status'})
sources['source_b'] = b

c = pd.read_parquet('/data/source_c/users.parquet').rename(columns={'userId': 'user_id', 'userName': 'name', 'joined': 'created_date', 'active': 'status'})
sources['source_c'] = c

for key in sources:
    df = sources[key]
    df['user_id'] = df['user_id'].astype(int)
    for col in ('name', 'email', 'status'):
        if col in df:
            df[col] = df[col].map(lambda v: None if pd.isna(v) else v)
    if 'status' in df:
        df['status'] = df['status'].map(to_status)
    if 'created_date' in df:
        df['created_date'] = pd.to_datetime(df['created_date']).dt.strftime('%Y-%m-%d')

merged = {}
for name in ('source_a', 'source_b', 'source_c'):
    for _, rec in sources[name].iterrows():
        uid = int(rec['user_id'])
        entry = merged.setdefault(uid, {})
        for col in ('name', 'email', 'created_date', 'status'):
            if col in rec and rec[col] is not None:
                entry.setdefault(col, {})[name] = rec[col]

fields = ('name', 'email', 'created_date', 'status')
conflicts = []
for uid in sorted(merged):
    entry = merged[uid]
    for col in fields:
        vals = entry.get(col, {})
        distinct = {v for v in vals.values() if v is not None}
        if len(distinct) > 1:
            selected = next((vals[s] for s in ('source_a', 'source_b', 'source_c') if s in vals), None)
            conflicts.append({'user_id': uid, 'field': col, 'values': {s: vals.get(s) for s in ('source_a', 'source_b', 'source_c')}, 'selected': selected})

out = pd.DataFrame([{'user_id': uid, **{c: e.get(c, {}).get('source_a', e.get(c, {}).get('source_b', e.get(c, {}).get('source_c'))) for c in fields}} for uid, e in sorted(merged.items())])
out['user_id'] = out['user_id'].astype(int)
out = out[['user_id', 'name', 'email', 'created_date', 'status']]
out.to_parquet('/app/merged_users.parquet', index=False)

json.dump({'total_conflicts': len(conflicts), 'conflicts': conflicts}, open('/app/conflicts.json', 'w'), indent=2)
print('done')
EOF
